
-- INSERT: ids are generated by Postgres, never supplied
INSERT INTO categories (name) VALUES ('Food'), ('Transport'), ('Entertainment');

INSERT INTO expenses (amount, description, date, category_id)
VALUES (5000, 'lunch', '2026-10-30', 1);

INSERT INTO expenses (amount, description, date, category_id)
VALUES (5000, 'dinner', '2026-09-30', 1);

INSERT INTO expenses (amount, description, date, category_id)
VALUES (500, 'movie', '2026-09-10', 3);


-- SELECT: read everything, then filter, then sort
SELECT * FROM categories;
SELECT * FROM expenses;
SELECT description, amount FROM expenses WHERE category_id = 1;
SELECT * FROM expenses WHERE amount > 10000 ORDER BY date DESC;

-- UPDATE: always SELECT with the same WHERE first
SELECT * FROM expenses WHERE id = 3;
UPDATE expenses SET amount = 5500 WHERE id = 3;

-- Transaction: nothing is permanent until COMMIT, so ROLLBACK undoes it
BEGIN;
UPDATE expenses SET amount = 1;
SELECT id, amount FROM expenses;
ROLLBACK;

-- DELETE: second one fails if the category still has expenses (foreign key)
DELETE FROM expenses WHERE id = 3;
DELETE FROM categories WHERE id = 1;

-- Totals
SELECT COUNT(*), SUM(amount) FROM expenses;
SELECT category_id, SUM(amount) FROM expenses GROUP BY category_id;

-- Month filter (the ?month=2026-10 endpoint): half-open range
SELECT * FROM expenses
WHERE date >= '2026-10-01' AND date < '2026-11-01';
